import { Paper, SxProps, Table, TableBody, TableCell, TableHead, TableRow, Theme } from "@mui/material";
import { ReactNode } from "react";

type CellAlign = "left" | "right" | "center";

export type DataGridColumn<T extends Record<string, ReactNode>> = {
  field: keyof T;
  headerName: string;
  align?: CellAlign;
  width?: number;
};

type CommonDataGridProps<T extends Record<string, ReactNode>> = {
  columns: DataGridColumn<T>[];
  rows: T[];
  getRowId?: (row: T, index: number) => string | number;
  emptyMessage?: string;
  withPaper?: boolean;
  sx?: SxProps<Theme>;
};

export default function CommonDataGrid<T extends Record<string, ReactNode>>({
  columns,
  rows,
  getRowId,
  emptyMessage = "No records found.",
  withPaper = true,
  sx
}: CommonDataGridProps<T>) {
  const table = (
    <Table>
      <TableHead>
        <TableRow>
          {columns.map((column) => (
            <TableCell
              key={String(column.field)}
              align={column.align ?? "left"}
              sx={column.width ? { width: column.width } : undefined}
            >
              {column.headerName}
            </TableCell>
          ))}
        </TableRow>
      </TableHead>
      <TableBody>
        {rows.length === 0 ? (
          <TableRow>
            <TableCell colSpan={columns.length} align="center">
              {emptyMessage}
            </TableCell>
          </TableRow>
        ) : (
          rows.map((row, index) => (
            <TableRow key={getRowId ? getRowId(row, index) : index} hover>
              {columns.map((column) => (
                <TableCell key={`${String(column.field)}-${index}`} align={column.align ?? "left"}>
                  {row[column.field]}
                </TableCell>
              ))}
            </TableRow>
          ))
        )}
      </TableBody>
    </Table>
  );

  if (!withPaper) {
    return table;
  }

  return <Paper sx={sx}>{table}</Paper>;
}
