import { Button, Chip, Paper, Typography } from "@mui/material";
import { ReactNode } from "react";
import CommonDataGrid, { DataGridColumn } from "@/components/common/CommonDataGrid";

const payslipRows = [
  { id: "PS-2401", employee: "Ava Johnson", month: "March 2026", amount: "$5,800", status: "Sent" },
  { id: "PS-2402", employee: "Liam Smith", month: "March 2026", amount: "$4,900", status: "Pending" },
  { id: "PS-2403", employee: "Noah Davis", month: "March 2026", amount: "$5,250", status: "Sent" }
];

export default function PayslipsPage() {
  const columns: DataGridColumn<(typeof payslipRows)[number] & { statusNode: ReactNode; action: ReactNode }>[] = [
    { field: "id", headerName: "Payslip ID" },
    { field: "employee", headerName: "Employee" },
    { field: "month", headerName: "Month" },
    { field: "amount", headerName: "Net Amount" },
    { field: "statusNode", headerName: "Status" },
    { field: "action", headerName: "Action" }
  ];

  const rows = payslipRows.map((row) => ({
    ...row,
    statusNode: (
      <Chip
        size="small"
        label={row.status}
        color={row.status === "Sent" ? "success" : "warning"}
        variant="outlined"
      />
    ),
    action: (
      <Button size="small" variant="outlined">
        Download
      </Button>
    )
  }));

  return (
    <Paper sx={{ p: 2.2 }}>
      <Typography variant="h5" fontWeight={800} sx={{ mb: 2 }}>
        Payslips
      </Typography>
      <CommonDataGrid columns={columns} rows={rows} getRowId={(row) => row.id} withPaper={false} />
    </Paper>
  );
}
